import{_ as a,o as r,c as e,a2 as d}from"./chunks/framework.BXzK3EA4.js";const f=JSON.parse('{"title":"인물·세력·생업","description":"","frontmatter":{},"headers":[],"relativePath":"world/Characters-Factions-and-Professions.md","filePath":"world/Characters-Factions-and-Professions.md"}'),o={name:"world/Characters-Factions-and-Professions.md"};function l(i,t,s,h,n,c){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="인물·세력·생업" tabindex="-1">인물·세력·생업 <a class="header-anchor" href="#인물·세력·생업" aria-label="Permalink to &quot;인물·세력·생업&quot;">​</a></h1><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/isometric-grammar.svg?raw=true" alt="인물과 파티가 어느 칸에 서 있고 어느 쪽을 보며 어디까지 보이는지"></p><h2 id="인물" tabindex="-1">인물 <a class="header-anchor" href="#인물" aria-label="Permalink to &quot;인물&quot;">​</a></h2><p>이름 있는 인물은 능력, 생업, 부상, 소속, 직위, 신념과 주요 사건 기억을 가집니다. 모든 인물 쌍의 관계를 저장하지 않고 친족, 사제, 지휘, 계약, 협력과 원한처럼 의미 있는 관계만 유지합니다.</p><h2 id="파티" tabindex="-1">파티 <a class="header-anchor" href="#파티" aria-label="Permalink to &quot;파티&quot;">​</a></h2><p>파티는 이동과 전투의 기본 단위입니다. 리더, 역할, 물자, 부상자, 현재 임무와 합법적인 위치를 가집니다. 리더가 죽거나 포획되면 정해진 승계 규칙으로 새 리더를 선택하고, 불가능하면 파티를 해산하거나 포로 집단으로 전환합니다.</p><h2 id="생업" tabindex="-1">생업 <a class="header-anchor" href="#생업" aria-label="Permalink to &quot;생업&quot;">​</a></h2><table tabindex="0"><thead><tr><th>생업</th><th>세계에서 하는 일</th><th>전술 기여</th></tr></thead><tbody><tr><td>정비사</td><td>전력, 셔터, 승강기, 차량 수리</td><td>장치 해제, 엄폐물 수리</td></tr><tr><td>물류상</td><td>물자 운송, 시장 연결, 통행 계약</td><td>보급 배치, 장비 교환</td></tr><tr><td>의무원</td><td>치료, 방역, 의약품 생산</td><td>부상 안정화, 상태 회복</td></tr><tr><td>순찰대</td><td>경로 안전, 호위, 질서 유지</td><td>진형 유지, 제압</td></tr><tr><td>전령</td><td>정보 전달, 외교 문서, 소문 수집</td><td>증원 요청, 지휘 범위</td></tr><tr><td>탐사원</td><td>폐쇄 구간 조사, 지도 갱신</td><td>함정 탐지, 우회로 확보</td></tr><tr><td>기록관</td><td>법통, 계약, 사건 원장 관리</td><td>목표 분석, 사기 지원</td></tr></tbody></table><h2 id="세력과-정통성" tabindex="-1">세력과 정통성 <a class="header-anchor" href="#세력과-정통성" aria-label="Permalink to &quot;세력과 정통성&quot;">​</a></h2><p>세력은 식량, 전력, 안전, 법통, 기술, 의료, 교역 같은 서로 다른 정통성 원천을 가집니다. 하나의 선악 수치로 판단하지 않습니다. 같은 정책도 어느 집단의 생존과 권리를 침해하는지에 따라 평가가 달라집니다.</p><h2 id="계승" tabindex="-1">계승 <a class="header-anchor" href="#계승" aria-label="Permalink to &quot;계승&quot;">​</a></h2><p>혈통뿐 아니라 양자, 사제, 직능 길드, 선거와 임명이 지도부 계승 경로가 됩니다. 지도자의 죽음은 곧바로 세력 삭제가 아니라 직위 공백, 경쟁 후보와 정책 분기를 만듭니다.</p><h2 id="십육국과-핵심-인물" tabindex="-1">십육국과 핵심 인물 <a class="header-anchor" href="#십육국과-핵심-인물" aria-label="Permalink to &quot;십육국과 핵심 인물&quot;">​</a></h2><ul><li><a href="/world/Sixteen-States.html">서울 십육국</a>: 총16국, 강국5·약소국11의 영토와 기반시설</li><li><a href="/world/Core-Characters.html">십육국 핵심 인물</a>: 국가별 지도자와 후계자의 성격, 야망, 공포와 촉발 사건</li><li><a href="/world/Cast-Index.html">인물 총람</a> · <a href="/world/Cast-Relations.html">관계 원장</a>: 16국 인물 412명과 인물 사이 관계 원장</li><li><a href="/world/Cast-Profile-Contract.html">인물 카드 계약</a>: 새 인물의 필수 칸. 출신 공동체, 언어, 징집 이력, 무장 접근</li><li><a href="/world/Conscription-Remnants.html">징집 잔존과 군 장부</a>: 징병제 명부가 동원잔존으로 남는 방식</li><li><a href="/world/Diaspora-Corridors.html">이주민 회랑</a> · <a href="/world/Cast-Corridors-Index.html">회랑 인물</a>: 한국 국적만 기본값이 아닌 회랑과 시드 인물</li><li><a href="/world/Ambitions-and-Relations.html">야망과 관계가 움직이는 정치</a>: 인물이 전쟁, 동맹, 배신과 계승을 결정하는 규칙</li><li><a href="/world/Scenario-Timeline.html">시나리오 타임라인</a>: 붕괴 이전부터 패권전까지 인물 조건으로 분기하는 연대기</li></ul>',14)])])}const p=a(o,[["render",l]]);export{f as __pageData,p as default};
